<script setup lang="ts">
import {computed,ref,watch,onScopeDispose} from 'vue'
import {Delete,Plus,ArrowUp,ArrowDown} from '@element-plus/icons-vue'
import {can,projectId} from '@/core/session'
import {ApiError,errorMessage,identityEpoch,onIdentityChange} from '@/core/http'
import ReferenceIcon from '@/ui/ReferenceIcon.vue'
import RuleActionDeviceTarget,{type RuleActionDeviceTarget as Target} from './RuleActionDeviceTarget.vue'
import {readAutomationTriggerChoices,readAutomationConditionChoices,type AutomationPropertyChoice} from './automation-property-model'
import {automationPropertyTrigger,automationPropertySourceSelection,automationChangedTriggerValue,automationTriggerConfig,automationTriggerPresentation,automationDeviceCondition,automationDeviceConditionAction,automationConditionPresentation,automationCurrentOperatorLabels,automationRangeCondition,automationOperatorLabels,automationObject,type AutomationNode,type AutomationPropertyTriggerValue,type AutomationSourceSelection,type AutomationOperator,type AutomationCurrentOperator,type AutomationCurrentCondition,type AutomationPredicateCondition} from './automation-editor-draft'
import {definitionUuid} from './device-task-definition-port'
import {ExactDecimal,parsePreprocessJson,writePreprocessJson,type ExactJson} from './preprocess-exact-json'
const props=withDefaults(defineProps<{value?:AutomationPropertyTriggerValue;condition?:AutomationNode;purpose?:'trigger'|'condition';triggerEnabled?:boolean;disabled?:boolean;sustained?:boolean}>(),{purpose:'trigger',triggerEnabled:true,sustained:true}),emit=defineEmits<{save:[config:AutomationPropertyTriggerValue,deviceName:string,enabled:boolean];saveCondition:[node:AutomationNode,deviceName:string];cancel:[];denied:[cause:ApiError]}>()
const conditionMode=computed(()=>props.purpose==='condition'),presentation=computed(()=>conditionMode.value?automationConditionPresentation:automationTriggerPresentation),readable=computed(()=>can('device:read'))
const initialCondition=props.condition?automationDeviceCondition(props.condition):undefined,initial=conditionMode.value?initialCondition:props.value?automationPropertyTrigger(props.value):undefined,enabled=ref(conditionMode.value?(initialCondition?.enabled??true):props.triggerEnabled)
const initialSource=automationPropertySourceSelection(props.value),limitSource=ref(props.value!==undefined&&initialSource!=='ALL'),sourceType=ref<Exclude<AutomationSourceSelection,'ALL'>>(initialSource&&initialSource!=='ALL'?initialSource:'REPORT')
const selectedSource=computed<AutomationSourceSelection>(()=>limitSource.value?sourceType.value:'ALL')
const durationSeconds=ref(initial&&'durationSeconds' in initial?Number(initial.durationSeconds):0)
const sustainedAllowed=computed(()=>props.sustained!==false&&!conditionMode.value&&(selectedSource.value==='ALL'||selectedSource.value==='REPORT'))
const durationOptions=[{value:0,label:'即时'},{value:10,label:'10秒'},{value:30,label:'30秒'},{value:60,label:'1分钟'},{value:300,label:'5分钟'},{value:600,label:'10分钟'},{value:1800,label:'30分钟'},{value:3600,label:'1小时'},{value:86400,label:'1天'}]
watch(selectedSource,value=>{if(value!=='ALL'&&value!=='REPORT')durationSeconds.value=0})
const wildcardDevice=!conditionMode.value&&automationObject(props.value)&&'deviceId' in props.value&&Object.keys(props.value).join(',')==='deviceId'&&definitionUuid(props.value.deviceId)?props.value.deviceId:undefined
const device=ref<Target>(),choices=ref<AutomationPropertyChoice[]>([]),rows=ref<{id:string;key:string;operator:AutomationCurrentOperator|'';raw:string;minRaw:string;maxRaw:string}[]>([]),relation=ref<'ALL'|'ANY'>(initial?.relation??'ALL'),loading=ref(false),targetBusy=ref(false),error=ref('')
let applied=false,turn=0,alive=true,controller:AbortController|undefined
const blank=()=>({id:crypto.randomUUID(),key:'',operator:'' as const,raw:'0',minRaw:'0',maxRaw:'0'})
function current(token:number,project:string,epoch:number){return alive&&token===turn&&project===projectId.value&&epoch===identityEpoch()&&readable.value}
function reset(){turn++;controller?.abort();device.value=undefined;rows.value=[];choices.value=[];loading.value=false;targetBusy.value=false;error.value=''}
function input(value:ExactJson|number){const exact=typeof value==='number'?new ExactDecimal(JSON.stringify(value)):value;try{return writePreprocessJson(exact,true)}catch{return writePreprocessJson(exact)}}
async function selected(target:Target|undefined){
 const token=++turn,project=projectId.value,epoch=identityEpoch();controller?.abort();device.value=target;choices.value=[];rows.value=[];error.value=''
 if(!target||!readable.value){loading.value=false;return}
 if(target.projectId!==project){error.value='请选择当前项目中的设备';loading.value=false;device.value=undefined;return}
 const restore=!applied&&initial?.deviceId===target.id;applied=true;controller=new AbortController();loading.value=true
 try{
  const result=await (conditionMode.value?readAutomationConditionChoices:readAutomationTriggerChoices)(project,target.id,controller.signal)
  if(!current(token,project,epoch))return
  choices.value=result;rows.value=restore?initial!.conditions.map(c=>automationRangeCondition(c)?{id:crypto.randomUUID(),key:c.propertyKey,operator:c.operator,raw:'0',minRaw:input(c.value.min),maxRaw:input(c.value.max)}:{id:crypto.randomUUID(),key:c.propertyKey,operator:c.operator,raw:input(c.value as ExactJson),minRaw:'0',maxRaw:'0'}):[blank()]
  if(!result.length)error.value='该设备没有关联的设备类型，无法设置属性条件'
 }catch(cause){if(current(token,project,epoch)){error.value=errorMessage(cause);if(cause instanceof ApiError&&[401,403].includes(cause.status))emit('denied',cause)}}finally{if(current(token,project,epoch))loading.value=false}
}
function definition(key:string){return choices.value.find(row=>row.key===key)}
function operators(key:string):AutomationCurrentOperator[]{const kind=definition(key)?.type;return kind==='NUMBER'?(conditionMode.value?['EQ','NE','GT','GTE','LT','LTE','IN_RANGE','OUT_RANGE']:['EQ','NE','GT','GTE','LT','LTE']):kind==='SWITCH'?['EQ']:['EQ','NE']}
function choose(row:{key:string;operator:AutomationCurrentOperator|'';raw:string;minRaw:string;maxRaw:string},key:string){if(props.disabled||!readable.value)return;row.key=key;row.operator='EQ';row.minRaw='0';row.maxRaw='0';const property=definition(key);row.raw=property?.type==='NUMBER'?'0':property?.type==='SWITCH'?'false':property?.type==='ENUM'&&!conditionMode.value?JSON.stringify(property.enumOptions?.[0]??''):'""'}
function isRange(operator:unknown){return operator==='IN_RANGE'||operator==='OUT_RANGE'}
function operatorLabel(operator:AutomationCurrentOperator){return conditionMode.value?automationCurrentOperatorLabels[operator]:automationOperatorLabels[operator as AutomationOperator]}
function operatorChanged(row:{operator:AutomationCurrentOperator|'';raw:string;minRaw:string;maxRaw:string},operator:AutomationCurrentOperator){if(props.disabled||!readable.value)return;const previous=isRange(row.operator);row.operator=operator;if(isRange(operator)&&!previous){row.minRaw='0';row.maxRaw='0'}else if(previous&&!isRange(operator))row.raw='0'}
function stepBound(row:{minRaw:string;maxRaw:string},field:'minRaw'|'maxRaw',direction:1|-1){const value={raw:row[field]};step(value,direction);row[field]=value.raw}
function text(raw:string){try{const value=parsePreprocessJson(raw);return typeof value==='string'?value:''}catch{return ''}}
function step(row:{raw:string},direction:1|-1){
 if(props.disabled||!readable.value||loading.value)return
 try{const value=parsePreprocessJson(row.raw.trim()||'0');if(!(value instanceof ExactDecimal))throw new Error('请填写有效数值');const exponent=value.exponent<0n?value.exponent:0n,digits=BigInt(value.digits.length)+value.exponent-exponent,unitDigits=1n-exponent;if(digits>1000n||unitDigits>1000n)throw new Error('数值步进结果超过当前精确输入范围');const coefficient=BigInt(value.digits)*(value.negative?-1n:1n)*10n**(value.exponent-exponent);row.raw=new ExactDecimal(`${coefficient+(direction===1?1n:-1n)*10n**(-exponent)}e${exponent}`).expanded();error.value=''}catch(cause){error.value=errorMessage(cause)}
}
function save(){
 if(props.disabled||!readable.value||loading.value||targetBusy.value)return
 try{
  if(!device.value||device.value.projectId!==projectId.value)throw new Error('请选择设备')
  const blankRows=rows.value.length===1&&rows.value.every(row=>!row.key&&!row.operator),legacyReport=props.value!==undefined&&automationPropertySourceSelection(props.value)==='REPORT'&&!Object.hasOwn(props.value,'sourceSelection')&&selectedSource.value==='REPORT'
  if(!conditionMode.value&&legacyReport&&wildcardDevice&&blankRows){emit('save',{deviceId:device.value.id},device.value.name,enabled.value);return}
  const conditions:AutomationCurrentCondition[]=!conditionMode.value&&!legacyReport&&blankRows?[]:rows.value.map(row=>{
   const property=definition(row.key);if(!property)throw new Error('请选择属性');if(!row.operator||!operators(row.key).includes(row.operator))throw new Error('请选择比较方式')
   if(isRange(row.operator)){
    if(!conditionMode.value||property.type!=='NUMBER'||row.operator!=='IN_RANGE'&&row.operator!=='OUT_RANGE')throw new Error('请选择比较方式')
    if(!row.minRaw.trim()||!row.maxRaw.trim())throw new Error('请输入范围值');const min=parsePreprocessJson(row.minRaw),max=parsePreprocessJson(row.maxRaw);if(!(min instanceof ExactDecimal)||!(max instanceof ExactDecimal))throw new Error('请输入范围值')
    return {propertyKey:row.key,operator:row.operator,value:{min,max}}
   }
   const value=parsePreprocessJson(row.raw)
   if(property.type==='NUMBER'&&!(value instanceof ExactDecimal)||property.type==='SWITCH'&&typeof value!=='boolean'||(property.type==='TEXT'||property.type==='ENUM')&&typeof value!=='string'||property.type==='ENUM'&&!conditionMode.value&&!property.enumOptions?.includes(String(value)))throw new Error('请填写属性条件的有效值')
   return {propertyKey:row.key,operator:row.operator as AutomationOperator,value:value as AutomationPredicateCondition['value']}
  })
  if(conditionMode.value)emit('saveCondition',automationDeviceConditionAction(device.value.id,enabled.value,relation.value,conditions,initialCondition?.schemaVersion),device.value.name)
  else emit('save',legacyReport?automationTriggerConfig(device.value.id,relation.value,conditions as AutomationPredicateCondition[],durationSeconds.value):automationChangedTriggerValue(device.value.id,selectedSource.value,relation.value,conditions as AutomationPredicateCondition[],durationSeconds.value),device.value.name,enabled.value)
 }catch(cause){error.value=errorMessage(cause)}
}
watch([projectId,readable],reset)
const dispose=onIdentityChange(reset);onScopeDispose(()=>{alive=false;turn++;controller?.abort();dispose()})
</script>
<template><el-dialog :model-value="true" :title="conditionMode?(condition?'编辑条件':'配置条件'):value?'编辑触发项':'配置触发项'" width="800px" :lock-scroll="false" :close-on-click-modal="false" :close-on-press-escape="!disabled" :show-close="!disabled" append-to-body @update:model-value="!disabled&&emit('cancel')">
 <div class="automation-trigger-type"><span :style="{background:presentation.background,color:presentation.color}"><ReferenceIcon :glyph="presentation.glyph"/></span><div><strong>{{presentation.label}}</strong><p>{{presentation.description}}</p></div></div>
 <el-form label-position="top" :disabled="disabled||!readable" :class="{'is-device-condition':conditionMode}"><el-form-item :label="conditionMode?'启用条件':'启用触发器'"><el-switch v-model="enabled" :aria-label="conditionMode?'启用条件':'启用触发器'" :disabled="disabled||!readable"/></el-form-item><el-form-item label="选择设备"><RuleActionDeviceTarget :initial-id="initial?.deviceId||wildcardDevice" :disabled="disabled||!readable" @selected="selected" @busy="targetBusy=$event"/></el-form-item>
 <template v-if="device"><el-form-item label="属性条件"><div class="automation-condition-list"><div v-for="(row,index) in rows" :key="row.id" class="automation-condition-row">
  <el-select :model-value="row.key" :aria-label="`条件属性 ${index+1}`" class="condition-property" placeholder="请选择属性" size="small" filterable :disabled="disabled||!readable||loading" @update:model-value="choose(row,$event)"><el-option v-for="property in choices" :key="property.key" :label="property.name===property.key?property.key:`${property.name} (${property.key})`" :value="property.key"/></el-select>
  <template v-if="definition(row.key)"><el-select :model-value="row.operator" @update:model-value="operatorChanged(row,$event)" :aria-label="`比较方式 ${index+1}`" placeholder="比较方式" size="small" class="condition-operator" :disabled="disabled||!readable"><el-option v-for="op in operators(row.key)" :key="op" :label="operatorLabel(op)" :value="op"/></el-select><div class="condition-value">
   <template v-if="definition(row.key)?.type==='NUMBER'"><div v-if="conditionMode&&isRange(row.operator)" class="condition-number-range"><div v-for="bound in (['minRaw','maxRaw'] as const)" :key="bound" class="condition-exact-number"><el-input v-model="row[bound]" :aria-label="`${bound==='minRaw'?'最小值':'最大值'} ${index+1}`" :placeholder="bound==='minRaw'?'最小':'最大'" size="small" inputmode="decimal" :disabled="disabled||!readable" @keydown.up.prevent="stepBound(row,bound,1)" @keydown.down.prevent="stepBound(row,bound,-1)"/><span class="condition-number-controls"><button type="button" :aria-label="`增加${bound==='minRaw'?'最小值':'最大值'} ${index+1}`" :disabled="disabled||!readable||loading" @click="stepBound(row,bound,1)"><el-icon><ArrowUp/></el-icon></button><button type="button" :aria-label="`减少${bound==='minRaw'?'最小值':'最大值'} ${index+1}`" :disabled="disabled||!readable||loading" @click="stepBound(row,bound,-1)"><el-icon><ArrowDown/></el-icon></button></span></div></div><div v-else-if="conditionMode" class="condition-exact-number"><el-input v-model="row.raw" :aria-label="`条件值 ${index+1}`" placeholder="数值" size="small" inputmode="decimal" :disabled="disabled||!readable" @keydown.up.prevent="step(row,1)" @keydown.down.prevent="step(row,-1)"/><span class="condition-number-controls"><button type="button" :aria-label="`增加条件数值 ${index+1}`" :disabled="disabled||!readable||loading" @click="step(row,1)"><el-icon><ArrowUp/></el-icon></button><button type="button" :aria-label="`减少条件数值 ${index+1}`" :disabled="disabled||!readable||loading" @click="step(row,-1)"><el-icon><ArrowDown/></el-icon></button></span></div><el-input v-else v-model="row.raw" :aria-label="`条件值 ${index+1}`" placeholder="数值" size="small" inputmode="decimal" :disabled="disabled||!readable"/></template>
   <el-select v-else-if="definition(row.key)?.type==='SWITCH'" v-model="row.raw" :aria-label="`条件值 ${index+1}`" placeholder="请选择" size="small" :disabled="disabled||!readable"><el-option label="ON" value="true"/><el-option label="OFF" value="false"/></el-select>
   <el-select v-else-if="!conditionMode&&definition(row.key)?.type==='ENUM'" :model-value="text(row.raw)" :aria-label="`条件值 ${index+1}`" placeholder="请选择枚举值" size="small" :disabled="disabled||!readable" @update:model-value="row.raw=JSON.stringify($event)"><el-option v-for="option in definition(row.key)?.enumOptions" :key="option" :label="option" :value="option"/></el-select>
   <el-input v-else :model-value="text(row.raw)" :aria-label="`条件值 ${index+1}`" placeholder="文本" size="small" :disabled="disabled||!readable" @update:model-value="row.raw=JSON.stringify($event)"/>
  </div></template><el-button :icon="Delete" text :aria-label="`移除条件 ${index+1}`" :disabled="disabled||!readable||loading||rows.length<=1" @click="rows.splice(index,1)"/>
 </div><el-button :icon="Plus" plain size="small" :disabled="disabled||!readable||loading||!choices.length||rows.length>=32" @click="rows.push(blank())">添加属性条件</el-button><div class="form-item-tip">支持添加多个属性条件，可选择条件关系。</div></div></el-form-item>
 <el-form-item v-if="rows.length>1" label="条件关系"><el-radio-group v-model="relation" aria-label="条件关系" :disabled="disabled||!readable"><el-radio value="ALL">满足全部（AND）</el-radio><el-radio value="ANY">满足任一（OR）</el-radio></el-radio-group></el-form-item><el-form-item v-if="!conditionMode&&sustainedAllowed" label="持续时间"><el-select v-model="durationSeconds" aria-label="持续时间" :disabled="disabled||!readable"><el-option v-for="item in durationOptions" :key="item.value" :label="item.label" :value="item.value"/></el-select><div class="form-item-tip">非“即时”时，条件需在真实属性上报中持续满足后再触发；没有后续上报不会补执行。</div></el-form-item><template v-if="!conditionMode"><el-form-item label="限制属性变化类型"><el-switch v-model="limitSource" aria-label="限制属性变化类型" :disabled="disabled||!readable"/><div class="form-item-tip automation-source-tip">开启后，仅指定的属性变化类型才会触发自动化。</div></el-form-item><el-form-item v-if="limitSource" label="选择属性变化类型"><el-radio-group v-model="sourceType" aria-label="选择属性变化类型" :disabled="disabled||!readable"><el-radio value="REPORT">属性上报</el-radio><el-radio value="PUSH">属性下发</el-radio><el-radio value="CLOUD">云端更新</el-radio></el-radio-group></el-form-item></template></template></el-form>
 <p v-if="loading">正在读取设备属性…</p><el-alert v-if="error" :title="error" type="warning" :closable="false"/>
 <template #footer><el-button :disabled="disabled" @click="emit('cancel')">取消</el-button><el-button type="primary" :disabled="disabled||!readable||loading||targetBusy||!device" @click="save">确定</el-button></template>
</el-dialog></template>
<style scoped>.automation-trigger-type{display:flex;align-items:center;gap:14px;padding:14px 16px;background:#f8f9fa;border-radius:8px;margin-bottom:20px}.automation-trigger-type>span{display:flex;align-items:center;justify-content:center;width:42px;height:42px;border-radius:10px;flex:none;font-size:22px}.automation-trigger-type strong{font-size:15px;font-weight:600;color:#333}.automation-trigger-type p{font-size:13px;color:#888;margin:4px 0 0}.automation-condition-list{width:100%}.automation-condition-row{display:flex;align-items:flex-start;gap:8px;margin-bottom:8px}.condition-property{width:200px;flex:1;min-width:0}.condition-operator{flex:1;min-width:100px}.condition-value{width:300px;max-width:45%}.condition-value>.el-select{width:100%}.form-item-tip{font-size:13px;color:#909399;margin-top:8px;line-height:1.4}.automation-source-tip{width:100%}.is-device-condition .condition-value{width:150px;max-width:30%}.condition-number-range{display:flex;gap:4px;width:100%}.condition-number-range>.condition-exact-number{min-width:0;flex:1}.condition-exact-number{position:relative;width:100%}.condition-exact-number :deep(.el-input__wrapper){padding-right:26px}.condition-number-controls{position:absolute;right:1px;top:1px;bottom:1px;width:23px;display:flex;flex-direction:column;border-left:1px solid #dcdfe6;border-radius:0 3px 3px 0;overflow:hidden}.condition-number-controls button{display:flex;align-items:center;justify-content:center;flex:1;min-height:0;padding:0;border:0;background:#f5f7fa;color:#909399;cursor:pointer;font-size:10px}.condition-number-controls button+button{border-top:1px solid #dcdfe6}.condition-number-controls button:hover{color:#409eff}.condition-number-controls button:disabled{cursor:not-allowed;color:#c0c4cc}</style>
